    }
    int n = arr.length;
    if (n == 0) {
        return 0.0;
    }
    try {
        int removeCount = (int) Math.floor(n * 0.05);
        if (2 * removeCount >= n) {
            // If removing would eliminate all elements, return 0.0
            return 0.0;
        }
        java.util.Arrays.sort(arr);
        double sum = 0.0;
        for (int i = removeCount; i < n - removeCount; i++) {
            sum += arr[i];
        }
        int remaining = n - 2 * removeCount;
        return sum / remaining;
    } catch (Exception e) {
        // In case of any unexpected runtime issues, return NaN
        return Double.NaN;
    }
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // odd number of elements cannot be fully paired
    }
    // Use array for counts if k is reasonably small, otherwise use HashMap
    // For simplicity, we assume k fits into array bounds
    int[] freq = new int[k];
    for (int val : arr) {
        int r = val % k;
        if (r < 0) {
            r += k;
        }
        freq[r]++;
    }
    for (int r = 0; r < k; r++) {
        int complement = (k - r) % k;
        if (freq[r] == 0) {
            continue;
        }
        if (r == complement) {
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }

    // Frequency array for all possible char values (0-65535)
    int[] freq = new int[65536];
    for (int i = 0; i < n; i++) {
        freq[s.charAt(i)]++;
    }

    StringBuilder result = new StringBuilder(n);
    int remaining = n;

    while (remaining > 0) {
        // Ascending pass: start with the smallest available character
        int cur = 0;
        while (cur < freq.length && freq[cur] == 0) {
            cur++;
        }
        if (cur >= freq.length) {
            break; // No characters left
        }
        result.append((char) cur);
        freq[cur]--;
        remaining--;

        while (remaining > 0) {
            int next = cur + 1;
            while (next < freq.length && freq[next] == 0) {
                next++;
            }
            if (next >= freq.length) {
                break;
            }
            result.append((char) next);
            freq[next]--;
            remaining--;
            cur = next;
        }

        // Descending pass: start with the largest available character
        int curDesc = freq.length - 1;
        while (curDesc >= 0 && freq[curDesc] == 0) {
            curDesc--;
        }
        if (curDesc < 0) {
            break; // No characters left
        }
        result.append((char) curDesc);
        freq[curDesc]--;
        remaining--;

        while (remaining > 0) {
            int prev = curDesc - 1;
            while (prev >= 0 && freq[prev] == 0) {
                prev--;
            }
            if (prev < 0) {
                break;
            }
            result.append((char) prev);
            freq[prev]--;
            remaining--;
            curDesc = prev;
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int sum = 0;
    for (int v : nums) sum += v;
    // dp[k] holds all possible sums using k elements
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new HashSet<>();
    dp[0].add(0);
    int processed = 0;
    for (int num : nums) {
        processed++;
        for (int k = Math.min(processed, n); k >= 1; k--) {
            for (int s : dp[k - 1]) {
                dp[k].add(s + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((long)sum * k % n != 0) continue;
        int target = (int)((long)sum * k / n);
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0 || n == 1) {
        // With 0 or 1 step, you can start beyond the first step and reach the top without paying anything.
        return 0;
    }
    // dp[i] is the minimum cost to reach step i (0-indexed).
    // We only need the previous two states to compute the current one.
    int prev2 = 0; // cost to reach step -1 (start point)
    int prev1 = 0; // cost to reach step 0
    for (int i = 2; i <= n; i++) {
        int stepFromOne = prev1 + cost[i - 1];   // come from step i-1
        int stepFromTwo = prev2 + cost[i - 2];   // come from step i-2
        int curr = Math.min(stepFromOne, stepFromTwo);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }
    String[] morse = {
        ".-","-...","-.-.","-..",".","..-.","--.","....","..",
        ".---","-.-",".-..","--","-.","---",".--.","--.-",".-.",
        "...","-","..-","...-",".--","-..-","-.--","--.."
    };
    java.util.Set<String> set = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue;
        }
        StringBuilder sb = new StringBuilder();
        for (char c : word.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            }
        }
        set.add(sb.toString());
    }
    return set.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int val = 0;
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    seen[val] = true;
    int count = 1;
    for (int i = k; i < n; i++) {
        val = ((val << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[val]) {
            seen[val] = true;
            count++;
            if (count == total) {
                return true;
            }
        }
    }
    return false;
}

