public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int leftNeeded = 0;  // count of unmatched '('
    int insertions = 0;  // count of inserted ')'
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            leftNeeded++;
        } else if (c == ')') {
            if (leftNeeded > 0) {
                leftNeeded--;  // match with a previous '('
            } else {
                insertions++;  // need an extra '(' before this ')'
            }
        } else {
            // Invalid character: skip or throw an exception depending on requirements
            // Here we choose to ignore it.
        }
    }
    // Any remaining '(' need a ')' to close
    return insertions + leftNeeded;
}

public int minOperations(int n) {
    if (n <= 1) {
        // For n == 0 or 1, no operations are needed
        return 0;
    }
    long operations = 0L;
    int startIdx = (n + 1) / 2; // first index where arr[i] > n
    for (int i = startIdx; i < n; i++) {
        int val = 2 * i + 1;
        operations += val - n; // val > n guaranteed here
    }
    // Since the problem guarantees the operations fit in an int
    return (int) operations;
}

