public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEndingHere = nums[0];
    int minEndingHere = nums[0];
    int maxSum = nums[0];
    int minSum = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        // Update max subarray ending here
        maxEndingHere = Math.max(val, maxEndingHere + val);
        maxSum = Math.max(maxSum, maxEndingHere);
        // Update min subarray ending here
        minEndingHere = Math.min(val, minEndingHere + val);
        minSum = Math.min(minSum, minEndingHere);
    }
    return Math.max(Math.abs(maxSum), Math.abs(minSum));
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int size = fibs.size();
        int next = fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }

    int count = 0;
    int remaining = k;
    // Greedy: pick the largest Fibonacci number <= remaining
    for (int i = fibs.size() - 1; remaining > 0; i--) {
        int fib = fibs.get(i);
        if (fib <= remaining) {
            remaining -= fib;
            count++;
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    int sqrt = (int) Math.sqrt(n);
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    int count = small.size() + large.size();
    if (k > count) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int idxInLarge = large.size() - (k - small.size());
        return large.get(idxInLarge);
    }
}

