public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array is null or empty");
    }
    int ones = 0;
    int twos = 0;
    for (int x : nums) {
        twos |= ones & x;      // update twos with bits that have appeared twice
        ones ^= x;             // update ones with bits that have appeared once
        int mask = ~(ones & twos); // remove bits that have appeared three times
        ones &= mask;
        twos &= mask;
    }
    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    Queue<Long> queue = new ArrayDeque<>();
    Set<Long> visited = new HashSet<>();
    Set<Integer> resultSet = new TreeSet<>();

    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (visited.contains(num)) {
            continue;
        }
        visited.add(num);

        if (num > high) {
            continue;
        }

        if (num >= low) {
            resultSet.add((int) num);
        }

        if (num == 0) {
            if (1 <= high) {
                queue.offer(1L);
            }
            continue;
        }

        int lastDigit = (int) (num % 10);

        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    result.addAll(resultSet);
    return result;
}

public static int countDigitOne(int n) {
    // If n is negative, there are no non‑negative integers to consider.
    if (n < 0) {
        return 0;
    }

    long total = 0;
    long divisor = 1; // 10^position, using long to avoid overflow

    while (divisor <= n) {
        long higher = n / (divisor * 10);
        long current = (n / divisor) % 10;
        long lower = n % divisor;

        if (current == 0) {
            total += higher * divisor;
        } else if (current == 1) {
            total += higher * divisor + lower + 1;
        } else {
            total += (higher + 1) * divisor;
        }

        // Move to the next higher digit place
        if (divisor > Long.MAX_VALUE / 10) {
            break; // Prevent potential overflow in the next loop
        }
        divisor *= 10;
    }

    // The result is guaranteed to fit in int for the problem constraints.
    return (int) total;
}

public static boolean isPowerOfTwo(int n) {
    try {
        if (n <= 0) {
            return false;
        }
        return (n & (n - 1)) == 0;
    } catch (Exception e) {
        return false;
    }
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("num must be non-negative");
    }
    try {
        if (num == 0) {
            return 0;
        }
        while (num >= 10) {
            int sum = 0;
            int current = num;
            while (current > 0) {
                sum += current % 10;
                current /= 10;
            }
            num = sum;
        }
        return num;
    } catch (Exception e) {
        throw new RuntimeException("Error computing digital root", e);
    }
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;

                int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                        Math.max(diag[i][j], anti[i][j]));
                if (localMax > max) {
                    max = localMax;
                }
            } else {
                horiz[i][j] = 0;
                vert[i][j] = 0;
                diag[i][j] = 0;
                anti[i][j] = 0;
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    boolean isNegative = n < 0;
    long absValue = Math.abs((long) n); // Use long to avoid overflow for Integer.MIN_VALUE
    String digits = Long.toString(absValue);
    int len = digits.length();
    int groupSize = 3;
    StringBuilder result = new StringBuilder();
    int firstGroup = len % groupSize;
    if (firstGroup == 0) firstGroup = groupSize;
    int count = 0;
    for (int i = 0; i < len; i++) {
        result.append(digits.charAt(i));
        count++;
        if (count == firstGroup) {
            if (i != len - 1) {
                result.append('.');
                count = 0;
            }
        } else if (count == groupSize) {
            if (i != len - 1) {
                result.append('.');
                count = 0;
            }
        }
    }
    if (isNegative) {
        result.insert(0, '-');
    }
    return result.toString();
}

public static int largestRectangleArea(int[] heights) {
    // Handle null or empty input
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int maxArea = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];

        // Validate the heights array for negative values
        if (currentHeight < 0) {
            throw new IllegalArgumentException("Heights must be non-negative.");
        }

        // Pop until the current bar is taller than the stack's top
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int topIndex = stack.pop();
            int height = heights[topIndex];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }

        stack.push(i);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0] != null ? mat[0].length : 0;
    if (n == 0) {
        return new int[0];
    }
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    int maxSum = m + n - 2;
    for (int sum = 0; sum <= maxSum; sum++) {
        if ((sum & 1) == 0) { // even sum: traverse from bottom to top
            int i = Math.min(m - 1, sum);
            int j = sum - i;
            while (i >= 0 && j < n) {
                result[idx++] = mat[i][j];
                i--;
                j++;
            }
        } else { // odd sum: traverse from top to bottom
            int i = Math.max(0, sum - n + 1);
            int j = sum - i;
            while (i < m && j >= 0) {
                result[idx++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    try {
        if (n <= 0) return -1;
        char[] digits = Integer.toString(n).toCharArray();
        int len = digits.length;
        int k = -1;
        for (int i = len - 2; i >= 0; i--) {
            if (digits[i] < digits[i + 1]) {
                k = i;
                break;
            }
        }
        if (k == -1) return -1;
        int l = -1;
        for (int i = k + 1; i < len; i++) {
            if (digits[i] > digits[k]) {
                if (l == -1 || digits[i] < digits[l]) {
                    l = i;
                }
            }
        }
        char tmp = digits[k];
        digits[k] = digits[l];
        digits[l] = tmp;
        for (int i = k + 2; i < len; i++) {
            int j = i;
            while (j > k + 1 && digits[j - 1] > digits[j]) {
                char c = digits[j];
                digits[j] = digits[j - 1];
                digits[j - 1] = c;
                j--;
            }
        }
        long result = 0;
        for (char c : digits) {
            result = result * 10 + (c - '0');
            if (result > Integer.MAX_VALUE) return -1;
        }
        return (int) result;
    } catch (Exception e) {
        return -1;
    }
}

public static boolean isBoomerang(int[][] points) {
    try {
        if (points == null || points.length != 3) {
            return false;
        }
        for (int i = 0; i < 3; i++) {
            if (points[i] == null || points[i].length != 2) {
                return false;
            }
        }
        int x1 = points[0][0], y1 = points[0][1];
        int x2 = points[1][0], y2 = points[1][1];
        int x3 = points[2][0], y3 = points[2][1];
        long cross = (long)(x2 - x1) * (y3 - y1) - (long)(y2 - y1) * (x3 - x1);
        return cross != 0;
    } catch (Exception e) {
        return false;
    }
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }
    try {
        int[] ugly = new int[n];
        ugly[0] = 1;
        int i2 = 0, i3 = 0, i5 = 0;
        long next2 = 2L, next3 = 3L, next5 = 5L;
        for (int i = 1; i < n; i++) {
            long minNext = Math.min(Math.min(next2, next3), next5);
            if (minNext > Integer.MAX_VALUE) {
                throw new ArithmeticException("Result exceeds integer limit.");
            }
            ugly[i] = (int) minNext;
            if (minNext == next2) {
                i2++;
                next2 = (long) ugly[i2] * 2L;
            }
            if (minNext == next3) {
                i3++;
                next3 = (long) ugly[i3] * 3L;
            }
            if (minNext == next5) {
                i5++;
                next5 = (long) ugly[i5] * 5L;
            }
        }
        return ugly[n - 1];
    } catch (ArrayIndexOutOfBoundsException | OutOfMemoryError e) {
        throw new IllegalArgumentException("Input too large to compute.", e);
    } catch (ArithmeticException e) {
        throw new IllegalArgumentException("Result too large for int type.", e);
    }
}

public static int calculateEnergy(String s) {
    // Handle null or empty string by returning 0 energy
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxRun = 1;           // maximum length of consecutive same characters found so far
    int currentRun = 1;       // length of the current run
    char previousChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        if (currentChar == previousChar) {
            // Continue the current run
            currentRun++;
        } else {
            // Run ended, update max if necessary
            if (currentRun > maxRun) {
                maxRun = currentRun;
            }
            // Reset for new character
            previousChar = currentChar;
            currentRun = 1;
        }
    }

    // Final check in case the longest run ends at the string's end
    if (currentRun > maxRun) {
        maxRun = currentRun;
    }

    return maxRun;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n < 1) {
        return result;
    }
    try {
        for (int i = 1; i <= 9 && i <= n; i++) {
            dfs(i, n, result);
        }
    } catch (Exception e) {
        // Unexpected exception, return what has been collected
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    result.add(current);
    if (current > n / 10) {
        return;
    }
    for (int digit = 0; digit <= 9; digit++) {
        long next = (long) current * 10 + digit;
        if (next > n) {
            break;
        }
        dfs((int) next, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int n = s.length();
    int i = 0;
    while (i < n) {
        if (s.charAt(i) == ' ') {
            result.append(' ');
            i++;
        } else {
            int j = i;
            while (j < n && s.charAt(j) != ' ') {
                j++;
            }
            for (int k = j - 1; k >= i; k--) {
                result.append(s.charAt(k));
            }
            i = j;
        }
    }
    return result.toString();
}
